from rest_framework import generics, permissions
from rest_framework.exceptions import PermissionDenied
from rest_framework.versioning import NamespaceVersioning
from .models import EmployeeCompensation

class EmployeeCompensationView(generics.RetrieveAPIView):
    serializer_class = CompensationSerializer
    permission_classes = [permissions.IsAuthenticated]
    versioning_class = NamespaceVersioning

    def get_queryset(self):
        if self.request.version == "internal":
            if not getattr(self.request.user, "is_internal_service_worker", False):
                raise PermissionDenied("Internal compensation access restricted to system services")
            return EmployeeCompensation.objects.all()
        return EmployeeCompensation.objects.filter(employee__user=self.request.user)
